s=s[:start]+'''/**
 * Rebuilds one tenant's index from scratch: the org's existing documents are
 * dropped, then every live project, every live issue of a live project and
 * every live comment on such an issue is re-upserted, walking every page.
 * Scoped to a single org on purpose: a full-fleet reindex is a sequence of
 * these, so one slow tenant cannot stall the rest, and no other org's
 * documents are touched.
 *
 * Archived rows are never read: an archived project hides its issues and
 * comments, an archived issue hides its comments, so none of them may have a
 * document once the rebuild is done.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteAllSearchDocuments(orgId);

    for await (const project of pages((cursor) =>
      projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      }),
    )) {
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
        continue;
      }

      for await (const issue of pages((cursor) =>
        issueRepo.listIssues({
          orgId,
          projectId: project.id,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      )) {
        try {
          await indexIssue(orgId, issue, project);
          result.processed += 1;

          for await (const comment of pages((cursor) =>
            commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: false,
              limit: PAGE_SIZE,
              cursor,
            }),
          )) {
            await indexComment(orgId, comment, issue, project);
            result.processed += 1;
          }
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

