import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = searchService.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });

const q = (t: any, text: string) => searchService.search(t.actors.admin, { orgId: t.org.id, q: text, kinds: [], limit: 25, cursor: null });

describe("tmp", () => {
  it("scenarios", async () => {
    const t = await createTenant("tmpa", "growth");
    const other = await createTenant("tmpb", "growth");
    await issueService.createIssue(other.actors.member, issueInput(other.org.id, other.project.id, { title: "Mark other" }));
    const i1 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Mark issue1" }));
    await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: i1.id, body: "Mark c1", parentId: null, mentionedUserIds: [] });
    expect((await q(t, "Mark")).total).toBe(2);
    await issueService.archiveIssue(t.actors.admin, t.org.id, i1.id);
    expect((await q(t, "Mark")).total).toBe(0);

    const p = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Kept Proj", key: "", description: "Mark proj", visibility: "public", leadId: null, color: "#000000", targetDate: null } as any);
    const i2 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, p.id, { title: "Mark i2" }));
    const i3 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, p.id, { title: "Mark i3" }));
    await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: i2.id, body: "Mark c2", parentId: null, mentionedUserIds: [] });
    await issueService.archiveIssue(t.actors.admin, t.org.id, i3.id);
    expect((await q(t, "Mark")).total).toBe(3);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: p.id, archiveIssues: false } as any);
    expect((await q(t, "Mark")).total).toBe(0);
    await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: i2.id, body: "Mark c3", parentId: null, mentionedUserIds: [] });
    await issueService.updateIssue(t.actors.member, { orgId: t.org.id, issueId: i2.id, title: "Mark i2 edited" });
    expect((await q(t, "Mark")).total).toBe(0);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(0);
    await projectService.restoreProject(t.actors.admin, t.org.id, p.id);
    const r = await q(t, "Mark");
    expect(r.total).toBe(4);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(4);

    // big workspace
    for (let k = 0; k < 250; k++) {
      const is = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: `Bulk ${k}` }) as any, t.userIds.member, 1000 + k);
      await commentRepo.insertComment({ orgId: t.org.id, issueId: is.id, body: `BulkC ${k}`, parentId: null, mentionedUserIds: [] } as any, t.userIds.member);
    }
    const otherBefore = await searchRepo.countIndexed(other.org.id);
    const res = await runSearchReindexJob(t.org.id);
    expect(res.failed).toBe(0);
    // projects: t.project + p = 2; i2 + c2 + c3 = 3; bulk 500
    expect(await searchRepo.countIndexed(t.org.id)).toBe(2 + 3 + 500);
    expect((await q(t, "Mark")).total).toBe(4);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: p.id, archiveIssues: true } as any);
    await projectService.restoreProject(t.actors.admin, t.org.id, p.id);
    expect((await q(t, "Mark")).total).toBe(1);
    await runSearchReindexJob(t.org.id);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(2 + 500);
  });
});
